<?php
require __DIR__.'/app/bootstrap.php';
$key=(string)($_GET['key']??$_POST['key']??'');$expected=(string)app_config('app.install_key');if($expected===''||!hash_equals($expected,$key)){http_response_code(403);exit('Kunci instalasi tidak valid. Tambahkan ?key=APP_INSTALL_KEY pada URL.');}
$message='';$error='';if(is_post()){try{verify_csrf();$schema=file_get_contents(__DIR__.'/database/schema.sql');if($schema===false)throw new RuntimeException('schema.sql tidak ditemukan.');db()->exec($schema);$name=trim((string)$_POST['name']);$email=filter_var($_POST['email'],FILTER_VALIDATE_EMAIL);$password=(string)$_POST['password'];if(!$email||strlen($password)<10)throw new RuntimeException('Email tidak valid atau password kurang dari 10 karakter.');$stmt=db()->prepare("INSERT INTO users(name,email,password_hash,role,is_active,created_at,updated_at) VALUES(?,?,?,'superadmin',1,NOW(),NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name),password_hash=VALUES(password_hash),is_active=1,updated_at=NOW()");$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$message='Instalasi berhasil. Hapus atau ubah nama file install.php setelah selesai.';}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instalasi Bujang Dayang</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#ecfdf5}.card{border:0;border-radius:24px}.btn{background:#047857;color:#fff}.btn:hover{background:#064e3b;color:#fff}</style></head><body><div class="container py-5"><div class="card shadow-lg p-4 p-lg-5 mx-auto" style="max-width:680px"><h1>Instalasi Website</h1><p class="text-secondary">Pastikan database sudah dibuat dan file <code>.env</code> telah dikonfigurasi.</p><?php if($message):?><div class="alert alert-success"><?= e($message) ?></div><a class="btn px-4" href="<?= url('admin/login.php') ?>">Masuk Dashboard</a><?php else:?><?php if($error):?><div class="alert alert-danger"><?= e($error) ?></div><?php endif;?><form method="post" class="row g-3"><?= csrf_field() ?><input type="hidden" name="key" value="<?= e($key) ?>"><div class="col-12"><label class="form-label">Nama Superadmin</label><input class="form-control" name="name" required value="Superadmin"></div><div class="col-12"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="col-12"><label class="form-label">Password (minimal 10 karakter)</label><input class="form-control" type="password" name="password" minlength="10" required></div><div class="col-12"><button class="btn btn-lg w-100">Jalankan Instalasi</button></div></form><?php endif;?></div></div></body></html>
